# Fix the verification - pytest import is fine (it's the test framework, not the library)
import subprocess

result = subprocess.run(
    ['python', '-m', 'pytest', '-q', '--no-cov', 'crucible_hidden'],
    capture_output=True, text=True
)

# Count properly from the summary line
lines = result.stdout.split('\n')
for line in lines:
    if 'failed' in line.lower() or 'passed' in line.lower():
        print(f"Summary: {line}")

# Also check individual test results
print("\n--- Detailed failures ---")
in_failures = False
for line in result.stdout.split('\n'):
    if 'FAILURES' in line:
        in_failures = True
    if in_failures:
        if line.startswith('___') and 'FAILED' not in line:
            continue
        if 'FAILED crucible_hidden' in line:
            print(line)
